#### ui/dialogue_box.gd
```
extends PanelContainer

signal line_finished

@export var characters_per_second: float = 30.0

var _tween: Tween

@onready var speaker_label: Label = $VBoxContainer/SpeakerLabel
@onready var dialogue_label: RichTextLabel = $VBoxContainer/DialogueLabel
@onready var continue_indicator: Label = $VBoxContainer/ContinueIndicator


func _ready() -> void:
	continue_indicator.visible = false


func _unhandled_input(event: InputEvent) -> void:
	if not is_showing():
		return

	if event.is_action_pressed("advance_dialogue"):
		advance()
		get_viewport().set_input_as_handled()


func show_line(speaker: String, text: String) -> void:
	var clean_speaker := speaker.strip_edges()
	if clean_speaker.is_empty():
		speaker_label.visible = false
	else:
		speaker_label.visible = true
		speaker_label.text = clean_speaker

	dialogue_label.text = text
	dialogue_label.scroll_to_line(0)
	dialogue_label.visible_ratio = 0.0
	set_indicator_visible(false)

	if _tween and _tween.is_running():
		_tween.kill()

	var total_chars := dialogue_label.get_total_character_count()
	if total_chars == 0 or characters_per_second <= 0.0:
		dialogue_label.visible_ratio = 1.0
		set_indicator_visible(true)
		return

	var duration := total_chars / characters_per_second
	_tween = create_tween()
	_tween.tween_property(dialogue_label, "visible_ratio", 1.0, duration)
	_tween.finished.connect(_on_typing_finished)


func advance() -> void:
	if is_typing():
		complete_line()
	else:
		set_indicator_visible(false)
		line_finished.emit()


func complete_line() -> void:
	if _tween and _tween.is_running():
		_tween.kill()
	dialogue_label.visible_ratio = 1.0
	set_indicator_visible(true)


func is_typing() -> bool:
	return _tween != null and _tween.is_running()


func set_indicator_visible(is_visible: bool) -> void:
	continue_indicator.visible = is_visible


func clear() -> void:
	if _tween and _tween.is_running():
		_tween.kill()
	dialogue_label.text = ""
	speaker_label.text = ""
	speaker_label.visible = false
	set_indicator_visible(false)


func is_showing() -> bool:
	return not dialogue_label.text.is_empty()


func _on_typing_finished() -> void:
	set_indicator_visible(true)
```

## Parte teorica della lezione (sintesi)
# La storia come dati
In questa lezione imparerai a strutturare la narrazione di una visual novel in un file JSON esterno e a creare la classe StoryPlayer per caricare la storia e avanzare una battuta alla volta, mantenendo separata la logica dei dati dall'interfaccia visiva.

Se dovessi scrivere i dialoghi del tuo gioco direttamente all'interno dello script dell'interfaccia, ogni minima modifica al testo o correzione di un refuso richiederebbe di riaprire il codice e rischiare di introdurre errori. Nelle visual novel, i dialoghi, i personaggi e le scene costituiscono i **dati** del gioco e devono rimanere separati dal **motore**, cioè dal codice che gestisce la logica di visualizzazione.

In questa lezione progetteremo la struttura dei dati di una scena usando il formato JSON, scriveremo una scena completa di venti battute e realizzeremo la classe `StoryPlayer`. Questa classe avrà il compito di leggere la storia da file e avanzare una battuta alla volta, senza che la finestra di dialogo debba sapere da dove arrivano i testi.

Per descrivere una singola battuta di dialogo in una visual novel servono principalmente due informazioni: **chi parla** (*speaker*) e **cosa dice** (*text*). 

Usando il formato JSON, possiamo rappresentare l'intera storia come una struttura dati ordinata. La radice sarà un oggetto contenente informazioni generali (come il titolo del capitolo) e un elenco ordinato (*array*) di battute, dove ogni battuta è un oggetto con le sue proprietà.

```gdscript
{
  "title": "Capitolo 1: Il Risveglio",
  "lines": [
    {
      "speaker": "Elena",
      "text": "Dove... dove mi trovo? Tutto questo buio..."
    },
    {
      "speaker": "Elena",
      "text": "L'ultima cosa che ricordo è la vecchia biblioteca in fondo alla strada."
    },
    {
      "speaker": "???",
      "text": "Ti sei svegliata, finalmente."
    },
    {
      "speaker": "Elena",
      "text": "Chi c'è? Chi sta parlando?"
    },
    {
      "speaker": "Marco",
      "text": "Tranquilla, non c'è motivo di spaventarsi. Sono Marco."
    },
    {
      "speaker": "Elena",
      "text": "Marco? Non ti conosco. Perché mi trovo qui?"
    },
    {
      "speaker": "Marco",
      "text": "Hai toccato il tomo rilegato in cuoio sul tavolo centrale, vero?"
    },
    {
      "speaker": "Elena",
      "text": "Sì... era aperto su una pagina strana. Un simbolo dorato lucidissimo."
    },
    {
      "speaker": "Marco",
      "text": "Quel simbolo è un sigillo d'accesso. Anche io sono finito qui nello stesso modo."
    },
    {
      "speaker": "Elena",
      "text": "Quindi questo posto... non è la biblioteca?"
    },
    {
      "speaker": "Marco",
      "text": "No. Questo è l'Archivio delle Storie. Un luogo fuori dal tempo."
    },
    {
      "speaker": "Elena",
      "text": "Fuori dal tempo? Sembra assurdo... devo subito tornare a casa!"
    },
    {
      "speaker": "Marco",
      "text": "Non è così semplice. La porta da cui sei entrata si è chiusa dietro di te."
    },
    {
      "speaker": "Elena",
      "text": "Ci deve essere un'altra uscita per forza. Ho la mia famiglia che mi aspetta!"
    },
    {
      "speaker": "Marco",
      "text": "Esiste una via di fuga, ma richiede di attraversare i diversi capitoli dell'Archivio."
    },
    {
      "speaker": "Elena",
      "text": "Capitoli? Che cosa significa esattamente?"
    },
    {
      "speaker": "Marco",
      "text": "Significa che dovrai vivere le storie custodite qui per sbloccare i passaggi."
    },
    {
      "speaker": "Elena",
      "text": "Se questo è l'unico modo per tornare indietro, allora sono pronta."
    },
    {
      "speaker": "Marco",
      "text": "Bene. Prendi questa lanterna, ti servirà lungo il cammino."
    },
    {
      "speaker": "Elena",
      "text": "Grazie, Marco. Cominciamo dall'inizio."
    }
  ]
}
```

Ora che i dati della storia sono strutturati, serve un componente che li legga e coordini l'avanzamento. Questo componente è la classe `StoryPlayer`.

`StoryPlayer` non sa come viene disegnato il testo a schermo né quale font viene usato: il suo solo compito è aprire il file JSON, estrarre l'elenco delle battute, tenere traccia dell'indice corrente (`_current_line_index`) e inviare i dati alla finestra di dialogo tramite la funzione `show_line()`. Quando l'utente chiede di avanzare e la riga completa viene mostrata, `DialogueBox` emette il segnale `line_finished`, segnalando a `StoryPlayer` che è il momento di passare alla battuta successiva.

Creare lo script per lo StoryPlayer
1. Nel pannello *FileSystem* (in basso a sinistra), fai clic destro sulla cartella `story/` e seleziona **New → Script...**.
2. Nella finestra di creazione, imposta il nome dello script su `story_player.gd` e verifica che erediti da `Node`.
3. Fai clic su **Create** per generare il file.

```gdscript
class_name StoryPlayer
extends Node

signal story_finished

@export var story_file_path: String = "res://story/intro.json"
@export var dialogue_box: PanelContainer

var _lines: Array = []
var _current_line_index: int = 0


func _ready() -> void:
	if dialogue_box:
		dialogue_box.line_finished.connect(_on_dialogue_box_line_finished)

	if load_story(story_file_path):
		start_story()


func load_story(path: String) -> bool:
	if not FileAccess.file_exists(path):
		print("Errore: file della storia non trovato: ", path)
		return false

	var file := FileAccess.open(path, FileAccess.READ)
	if not file:
		print("Errore durante l'apertura del file: ", path)
		return false

	var json := JSON.new()
	var parse_result := json.parse(file.get_as_text())
	if parse_result != OK:
		print("Errore nel parsing del JSON: ", json.get_error_message())
		return false

	var data: Dictionary = json.data
	if not data.has("lines"):
		print("Errore: la chiave 'lines' non è presente nel file JSON.")
		return false

	_lines = data["lines"]
	_current_line_index = 0
	return true


func start_story() -> void:
	if _lines.is_empty():
		return
	_current_line_index = 0
	_show_current_line()


func advance() -> void:
	_current_line_index += 1
	if _current_line_index < _lines.size():
		_show_current_line()
	else:
		if dialogue_box:
			dialogue_box.clear()
		story_finished.emit()


func _show_current_line() -> void:
	if _current_line_index < 0 or _current_line_index >= _lines.size():
		return

	var line_data: Dictionary = _lines[_current_line_index]
	var speaker: String = line_data.get("speaker", "")
	var text: String = line_data.get("text", "")

	if dialogue_box:
		dialogue_box.show_line(speaker, text)


func _on_dialogue_box_line_finished() -> void:
	advance()
```

(attenzione) Quando usi `JSON.new()` e `json.parse()`, verifica sempre che il risultato sia uguale a `OK`. Se il file JSON contiene un errore di sintassi (come una virgola mancante o virgolette non chiuse), `json.parse()` fallirà e tentare di accedere a `json.data` produrrà un errore a runtime.

