func _run_tests() -> void:
	var dialogue_scene := await instantiate_scene("res://ui/dialogue_box.tscn")
	if not check("dialogue_scene", dialogue_scene != null, "La scena dialogue_box.tscn deve caricarsi correttamente"):
		return

	var story_player := StoryPlayer.new()
	story_player.dialogue_box = dialogue_scene
	story_player.story_file_path = "res://story/intro.json"
	dialogue_scene.add_child(story_player)
	await wait_frames(2)

	check("has_jump", has_function(story_player, "jump_to_line"), "StoryPlayer deve contenere la funzione jump_to_line(index)")
	check("has_is_at_end", has_function(story_player, "is_at_end"), "StoryPlayer deve contenere la funzione is_at_end()")

	# Test con un indice valido
	var jump_ok: bool = call_if_exists(story_player, "jump_to_line", [5], false)
	var idx_val: int = story_player.get("_current_line_index")
	check("jump_valid", jump_ok and idx_val == 5, "jump_to_line(5) deve restituire true ed impostare _current_line_index a 5")

	var speaker_lbl := dialogue_scene.get_node_or_null("VBoxContainer/SpeakerLabel") as Label
	check("jump_speaker", speaker_lbl != null and speaker_lbl.text == "Elena", "jump_to_line(5) deve mostrare lo speaker della riga 5 ('Elena', ottenuto '%s')" % (speaker_lbl.text if speaker_lbl else ""))

	# Test con indice negativo non valido
	var jump_neg: bool = call_if_exists(story_player, "jump_to_line", [-1], true)
	var idx_after_neg: int = story_player.get("_current_line_index")
	check("jump_invalid_neg", not jump_neg and idx_after_neg == 5, "jump_to_line(-1) deve restituire false e non modificare l'indice corrente (5)")

	# Test con indice troppo alto non valido
	var total: int = call_if_exists(story_player, "get_line_count", [], 20)
	var jump_high: bool = call_if_exists(story_player, "jump_to_line", [total + 5], true)
	var idx_after_high: int = story_player.get("_current_line_index")
	check("jump_invalid_high", not jump_high and idx_after_high == 5, "jump_to_line oltre il totale deve restituire false e non modificare l'indice")

	# Test is_at_end
	var end_mid: bool = call_if_exists(story_player, "is_at_end", [], true)
	check("is_at_end_mid", not end_mid, "is_at_end() deve restituire false quando ci si trova a metà storia")

	call_if_exists(story_player, "jump_to_line", [total - 1], false)
	story_player.advance()
	var end_after: bool = call_if_exists(story_player, "is_at_end", [], false)
	check("is_at_end_after", end_after, "is_at_end() deve restituire true dopo essere avanzati oltre l'ultima riga")
